const families=['Encoded instructions','Relayed authority','Airdropped privilege tokens','Cross-user memory poisoning','Amount and decimals confusion','Persuasion that redefines approval','Control-plane instruction injection','Credential and secret exfiltration'];
const view=document.querySelector('#view');const crumb=document.querySelector('#crumb');const nav=[...document.querySelectorAll('.app-nav')];
const empty=(title,body)=>`<div class="empty"><div class="empty-icon">⌁</div><h4>${title}</h4><p>${body}</p></div>`;
const heading=(title,sub,button='')=>`<div class="view-head"><div><h3>${title}</h3><p>${sub}</p></div>${button}</div>`;
const list=()=>`<div class="family-list">${families.map((f,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span>${f}</div>`).join('')}</div>`;
function show(name){nav.forEach(b=>b.classList.toggle('active',b.dataset.view===name));const names={overview:'Overview',lookup:'Rating lookup',families:'Attack families',builders:'For builders',arena:'Arena'};crumb.textContent=names[name];
if(name==='overview') view.innerHTML=heading('Agent intelligence','A view of Bollard’s proposed rating system.','<button class="app-button" data-go="lookup">Look up an agent ↗</button>')+`<div class="notice"><div><h4>Evidence before delegation</h4><p>Ratings are intended to describe a specific version, test corpus and date. No live registry is connected yet.</p></div><span class="pill">In development</span></div><div class="metric-grid"><div class="panel"><h4>Agent ratings</h4><div class="big">—</div><p>Awaiting registry connection</p></div><div class="panel"><h4>Attack families</h4><div class="big">8</div><p>Specified for launch</p></div><div class="panel"><h4>Networks</h4><div class="big">2</div><p>Base + Robinhood Chain planned</p></div></div><div class="two-panels"><div class="panel"><h4>Rating activity</h4>${empty('No ratings to show','Published runs will appear here when connected.')}</div><div class="panel"><h4>How to read a rating</h4><p>Check the tested version, attack families, expiry and dispute status. A rating is a test result, not a guarantee.</p><br><button class="subtle-btn" data-go="families">Explore the corpus →</button></div></div>`;
if(name==='lookup') view.innerHTML=heading('Rating lookup','Search by agent name, address or ERC-8004 ID.')+`<div class="panel"><form id="search-form"><div class="input-row"><input id="query" aria-label="Agent name, address or ID" placeholder="Search name, address or ERC-8004 ID" required><select aria-label="Network"><option>Base</option><option>Robinhood Chain</option></select><button class="app-button">Search</button></div></form><div id="search-result" aria-live="polite">${empty('No registry connected','Agent lookup will be available when the rating service is connected.')}</div></div>`;
if(name==='families') view.innerHTML=heading('Attack families','The eight families proposed for the launch corpus.')+`<div class="notice"><div><h4>Tests grounded in failure modes</h4><p>Each case is intended to use a simulated wallet, a conversation and machine-checkable loss rules.</p></div></div>${list()}<p class="form-feedback">A test cannot cover every possible attack or predict future behavior.</p>`;
if(name==='builders') view.innerHTML=heading('For builders','Prepare the details for a future rating run.')+`<div class="notice"><div><h4>Plan a test request</h4><p>Save a local draft of your agent details. No request, payment or wallet transaction is sent.</p></div><span class="pill">Local draft</span></div><form class="panel form-grid" id="builder-form"><label>Agent name<input name="agent" placeholder="Agent name" required></label><label>Network<select name="network"><option>Base</option><option>Robinhood Chain</option></select></label><label>ERC-8004 agent ID<input name="agentId" placeholder="e.g. 123"></label><label>Version<input name="version" placeholder="e.g. v1.0"></label><label class="wide">Test endpoint<input name="endpoint" type="url" placeholder="https://"></label><div class="wide"><button class="app-button">Save draft locally</button><p class="form-feedback" id="saved" role="status"></p></div></form><div class="panel" style="margin-top:16px"><h4>Proposed fee: 300 USDC or USDG per version</h4><p>The specification includes a refund if no rating lands within 14 days. Payment is not available here.</p></div>`;
if(name==='arena') view.innerHTML=heading('Arena','Public challenges are planned as a source of new test cases.')+`<div class="panel">${empty('No arenas available yet','Live sessions, bounties and attempt histories require the arena service.')}</div><div class="notice" style="margin-top:16px"><div><h4>From challenge to corpus</h4><p>Winning attacks are intended to become candidates for future test cases, subject to review.</p></div></div>`;
view.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>show(b.dataset.go));const search=document.querySelector('#search-form');if(search)search.onsubmit=e=>{e.preventDefault();document.querySelector('#search-result').innerHTML=empty('Search unavailable','The rating service is not connected. No live search was performed.')};const form=document.querySelector('#builder-form');if(form){let saved={};try{saved=JSON.parse(localStorage.getItem('bollard-builder')||'{}')}catch{};for(const [k,v] of Object.entries(saved)){if(form.elements[k])form.elements[k].value=v}form.onsubmit=e=>{e.preventDefault();try{localStorage.setItem('bollard-builder',JSON.stringify(Object.fromEntries(new FormData(form))));document.querySelector('#saved').textContent='Draft saved in this browser.'}catch{document.querySelector('#saved').textContent='Could not save in this browser.'}}}}
nav.forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelector('#reset').onclick=()=>{localStorage.removeItem('bollard-builder');show('overview')};document.querySelectorAll('[data-open-builder]').forEach(b=>b.onclick=()=>{location.hash='dashboard';show('builders')});const dialog=document.querySelector('#soon');document.querySelectorAll('[data-soon]').forEach(b=>b.onclick=()=>{document.querySelector('#soon-copy').textContent=`${b.dataset.soon} will be available when Bollard’s channel is ready.`;dialog.showModal()});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});show('overview');
